/**
 * Добавление нового виджета.
 */
class Custom_Site_Enhancements_Widget extends WP_Widget {

    /**
     * Считать количество вложенных строк.
     *
     * @param string $text Текст для подсчета строк.
     *
     * @return int
     */
    public static function count_lines( $text ) {
        $lines = explode( "\n", $text );
        $count = count( $lines );

        return $count;
    }

    /**
     * Считать количество слов в тексте.
     *
     * @param string $text Текст для подсчета слов.
     *
     * @return int
     */
    public static function count_words( $text ) {
        $words = preg_split( "/[\s,]+/", $text, -1, PREG_SPLIT_NO_EMPTY );
        $count = count( $words );

        return $count;
    }

    /**
     * Создание виджета.
     */
    public function __construct() {
        parent::__construct(
            'custom_site_enhancements_widget',
            __( 'Custom Site Enhancements Widget', 'custom-site-enhancements' ),
            array( 'description' => __( 'Custom Widget', 'custom-site-enhancements' ) )
        );
    }

    /**
     * Вывод виджета.
     *
     * @param array $args
     * @param array $instance
     */
    public function widget( $args, $instance ) {

        $title = apply_filters( 'widget_title', $instance['title'] );
        $content = $instance['content'];

        echo $args['before_widget'];

        if ( ! empty( $title ) ) {
            echo $args['before_title'] . $title . $args['after_title'];
        }

        echo '<div class="custom-site-widget">' . Do_shortcode( $content ) . '</div>';

        echo $args['after_widget'];

    }

    /**
     * Форма настройки виджетов.
     *
     * @param array $instance
     *
     * @return string
     */
    public function form( $instance ) {

        $title = ! empty( $instance['title'] ) ? $instance['title'] : '';
        $content = ! empty( $instance['content'] ) ? $instance['content'] : '';

        ?>
        <p>
            <label for="<?php echo $this->get_field_id( 'title' ); ?>"><?php _e( 'Title:' ); ?></label>
            <input class="widefat" id="<?php echo $this->get_field_id( 'title' ); ?>" name="<?php echo $this->get_field_name( 'title' ); ?>" type="text" value="<?php echo esc_attr( $title ); ?>">
        </p>

        <p>
            <label for="<?php echo $this->get_field_id( 'content' ); ?>"><?php _e( 'Content:' ); ?></label>
            <textarea class="widefat" id="<?php echo $this->get_field_id( 'content' ); ?>" name="<?php echo $this->get_field_name( 'content' ); ?>"><?php echo esc_textarea( $content ); ?></textarea>
        </p>

        <?php
    }

    /**
     * Сaved widget settings.
     *
     * @param array $new_instance
     * @param array $old_instance
     *
     * @return array
     */
    public function update( $new_instance, $old_instance ) {

        $instance = array();
        $instance['title'] = ( ! empty( $new_instance['title'] ) ) ? strip_tags( $new_instance['title'] ) : '';
        $instance['content'] = ( ! empty( $new_instance['content'] ) ) ? sanitize_textarea_field( $new_instance['content'] ) : '';

        return $instance;
    }

}

