Поскольку значение постоянной Планка (h) изначально необходимо вычислить, для этого код C# будет выглядеть следующим образом:

```csharp
using System;

namespace PlanckConstantCalculator
{
    class Program
    {
        static void Main(string[] args)
        {
            double wavelength = 600e-9; // перевести нм в метры
            double speedOfLight = 299792458;

            double energy = (6.62607004e-34 * speedOfLight * Constants.WavelengthToFrequency(wavelength)); // вычислить энергию с учетом длины волны

            double planckConstant = energy / speedOfLight;

            Console.WriteLine("Значение постоянной Планка (h) равно: " + planckConstant.ToString("F10") + " Дж с");
            Console.WriteLine("Энергия фотона с длиной волны 600 нм равна: " + energy.ToString("F10") + " Дж");

            Console.ReadKey();
        }
    }

    static class Constants
    {
        public static double WavelengthToFrequency(double wavelength)
        {
            return Constants.SpeedOfLight / wavelength;
        }

        public static double SpeedOfLight => 299792458;
    }
}
```

