```java
import com.datafaker.core.DataFaker;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.github.benas.randombeans.api.EnhancedRandomBuilder;
import io.github.benas.randombeans.api.RandomBeans;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.core.env.Environment;
import org.springframework.http.*;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultActions;
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders;
import org.springframework.test.web.servlet.result.MockMvcResultMatchers;
import org.springframework.util.MultiValueMap;
import org.springframework.web.bind.annotation.RequestHeader;

import java.nio.charset.Charset;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

public class InvoiceStepDefinition {

    private final MockMvc mvc;
    private final DataFaker datafaker;
    private final ObjectMapper mapper;
    private final Environment environment;

    @Autowired
    public InvoiceStepDefinition(MockMvc mvc, DataFaker datafaker, ObjectMapper mapper, Environment environment) {
        this.mvc = mvc;
        this.datafaker = datafaker;
        this.mapper = mapper;
        this.environment = environment;
    }

    @io.cucumber.java.en.Given("A valid invoice request with the following data:")
    public void given_valid_invoice_request(Map<String, String> tableArgs) throws Exception {
        Map<String, Object> invoiceRequest = RandomBeans
                .withScope(InvoiceEntity.class)
                .excludeProperties("id")
                .and()
                .randomize("invoiceNumber", "invoiceDate", "customerId", "totalAmountDue")
                .build();

        for (Map.Entry<String, String> entry : tableArgs.entrySet()) {
            invoiceRequest.put(entry.getKey(), entry.getValue());
        }

        List<String> headers = new ArrayList<>();
        headers.add("Content-Type");
        headers.add("Authorization");

        List<String> headerValues = new ArrayList<>();
        headerValues.add("application/json; charset=UTF-8");
        String authServiceUrl = environment.getProperty("spring.security.oauth2.client.registration.oauth2-authentication-provider.authorization-uri");
        String token = datafaker.oauth2()
                .accessToken(
                        authServiceUrl.replace("{scope}", "read write"),
                        "client-id",
                        "client-secret",
                        "password",
                        "username",
                        "password"
                )
                .accessToken();

        headerValues.add("Bearer " + token);

        MultiValueMap<String, String> requestHeaders = new HashMap<>();
        for (int I = 0; I < headers.size(); i++) {
            requestHeaders.add(headers.get(i), headerValues.get(i));
        }

        String requestJson = mapper.writeValueAsString(invoiceRequest);
        HttpEntity<String> requestEntity = new HttpEntity<>(requestJson, requestHeaders);

        mvc.perform(MockMvcRequestBuilders.post("/invoices")
                .contentType(MediaType.APPLICATION_JSON)
                .charset(Charset.forName("UTF-8"))
                .content(requestJson)
                .headers(requestHeaders))
                .andExpect(status().isCreated());
    }

    // andre здесь идут остальные шаги, которые описывают действия при успешном создании
    // или проваленном создании транзакции в Oracle EBS.
}
