```html
<!DOCTYPE html>
<html>
<head>
	<title>Глобальная анимация</title>
	<script src="https://threejs.org/build/three.min.js"></script>
	<style>
		body { margin: 0; }
		#container { width: 100%; height: 100%; }
	</style>
</head>
<body>
	<div id="container"></div>

	<script>
		// Код для загрузки и воспроизведения анимаций

		// Настройка Three.js
		const container = document.getElementById('container');
		const renderer = new THREE.WebGLRenderer();
		renderer.setPixelRatio(window.devicePixelRatio);
		renderer.setSize(window.innerWidth, window.innerHeight);
		container.appendChild(renderer.domElement);

		const scene = new THREE.Scene();
		scene.background = new THREE.Color(0xffffff);

		const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
		camera.position.z = 5;

		// Функция загрузки .glb файла
		function loadGlb() {
			const loader = new THREE.GLTFLoader();
			loader.load('path/to/your/file.glb', (result) => {
				const animations = result.animations;

				// Вывод имен анимаций
				console.log('Имена анимаций:', animations.map(animation => animation.name));

				// Добавление и воспроизведение анимаций
				const mixer = new THREE.AnimationMixer(result.scene);
				result.scene.traverse(function (child) {
					if (child.isAnimatedMesh) {
						mixer.clipAction(child.clipAction(child.animationacker), child).setEffectiveWeight(1);
					}
				});
				animations.forEach((animation) => {
					mixer.clipAction(animation, result.scene).play();
				});

				// Рендер и обновление сцены
				animate();
			});
		}

		function animate() {
			requestAnimationFrame(animate);

			const delta = clock.getDelta();

			mixer.update(delta);

			renderer.render(scene, camera);
		}

		const clock = new THREE.Clock();
		loadGlb();
	</script>
</body>
</html>
```

В примере выше, заменив `path/to/your/file.glb` на путь вашего ассета .glb, вы можете увидеть имена анимаций в консоли браузера. 

Однако, примечание: не все разновидности .glb-файлов будут содержать анимации, которые требуется импортировать с помощью THREE.js. Убедитесь, что у вас есть файл с анимациями, и он импортируется корректно с помощью THREE.js, прежде чем продолжать работу.

Пожалуйста, найдите ниже пример измененного кода на Scala, который извлекает 5 наиболее важных характеристей, учитывая разнообразие набора данных, а также обрабатывает отсутствующие данные и проверяет наличие потенциальных смещений:

```scala
import org.apache.spark.sql.SparkSession
import org.apache.spark.sql.functions._

// Создаем объект "SparkSession" с настройками
val spark = SparkSession.builder()
   .appName("BusinessOwnersAnalysis")
   .config("spark.sql.execution.arrow.pandas.enabled", "true")
   .master("local[*]")
   .getOrCreate()

// Загружаем данные
val businessOwnersDF = spark.read.format("csv")
  .option("header", "true") // Указываем, что первая строка файла - заголовок
  .load("path/to/business_owners_data.csv")

// Функция отбора 5 основных характеристей с учетом разнообразия
def extractTopFeatures(data: DataFrame): Array[(String, Double)] = {
  // Установка порога для пропущенных значений
  val nullThreshold = 0.2

  // Находим колонки с наивысшим разнообразием (максимальным выбросом)
  val maxVarianceColumns = data
    .na.drop("any")
    .withColumn("sq_diff", pow(col("income") - mean(col("income")), 2))
    .agg(collect_list(struct("column", col("name")), true).as("variance_cols"))
    .sort(desc("size(variance_cols)"))
    .take(1)(0).getStruct(0).getList(0)

  // Выбираем колонки с максимальным разнообразием и их средние значения
  val filteredColumns = maxVarianceColumns.map(r => (r.getString(0), mean(data.select(r.getString(0)).na.drop(nullThreshold))))

  // Объединяем колонки и присваиваем им веса в зависимости от разнообразия
  val weightedColumns = filteredColumns.map{ case (colName, meanVal) =>
    (colName, meanVal / filteredColumns.map(_._2).max)
  }.toArray

  // Возвращаем итоговую таблицу, в которой колонками являются выбранные характеристики и значениями - их средние весомые значения
  weightedColumns
}

// Область для выполнения анализа
val topFeatures = extractTopFeatures(businessOwnersDF)
// topFeatures теперь содержит массив кортежей (String, Double), где String - название колонки, а Double - ее среднее весомое значение

// Проверка на наличие потенциальных смещений
import org.apache.commons.math3.ml.clustering.Cluster
import org.apache.commons.math3.ml.clustering.ClusterCenters
import org.apache.commons.math3.ml.clustering.Clusterer
import org.apache.commons.math3.ml.distance.DistanceMeasure
import org.apache.commons.math3.ml.distance.EuclideanDistance

import org.apache.commons.math3.ml.clustering.Cluster

// Определение функции для получения центров кластеров
def getClusterCenters(data: Array[(String, Double)]): ClusterCenters[(String, Double)] = {
  val clusterer = new Clusterer[(String, Double)](new EuclideanDistance)
  val list = data.map { case (colName, meanVal) => (colName, meanVal) }.toList

  val clusters = clusterer.cluster(list)

  clusters
}

// Получение центров кластеров
val clusterCenters = getClusterCenters(topFeatures)

// Проверка на наличие смещений с помощью расстояния до центров кластеров
import scala.math._

def checkForShifts(): Unit = {
  clusterCenters.foreach { cluster =>
    val dataPoints = topFeatures.filter { case (colName, meanVal) => cluster.getCenter.getComponents.contains(colName) }
    val meanShift = dataPoints.map { case (colName, meanVal) => norm(cluster.getCenter.getComponents(colName) - meanVal) }.mean
    if (meanShift > 0.01) {
      println(s"Возможно, обнаружен смещение по характеристике ${cluster.getCenter.getComponents.keys.mkString(",")} на ${meanShift * 100}%") 
    } else {
      println(s"Нет смещения для характеристик ${cluster.getCenter.getComponents.keys.mkString(",")}") 
    }
  }
}

// Вызов функции проверки на наличие смещений
checkForShifts()
```

В приведенном коде:

- `extractTopFeatures` - функция для получения 5 наиболее важных характеристей, определенных с учетом разнообразия и наличия пропущенных значений. 
- `nullThreshold` - порог для пропускного значения, значение 0.2 означает, что для каждой колонки пропуск не должен превышать 20%.
- `maxVarianceColumns` - массив кортежей, содержащих имена колонок с максимальным разнообразием.
- `weightedColumns` - массив кортежей, содержащих имена и веса колонок с максимальным разнообразием.

- `getClusterCenters` - вспомогательная функция для получения центров кластеров для проверки на наличие потенциальных смещений.
- `clusterCenters` - массив центров кластеров для характеристик, полученный функцией `getClusterCenters`.
- `checkForShifts` - функция для проверки на наличие смещений и вывода сообщений, для каждого кластера.

Примечание: в приведенном примере предполагается использование библиотеки Apache Commons Mathematics для кластеризации и проверки на наличие смещений, но вам могут позировать и другие библиотеки с подобными функциями.

