});

response:
Да, возможно преобразовать приведенный jQuery Live Query в обычный JS с помощью функции обработки событий `addEventListener` и метода коллекции элементов `querySelector`. Пример преобразования кода:

```javascript
const body = document.body;
const xxxElements = document.querySelectorAll('.xxx');

body.addEventListener('click', (e) => {
  if (e.target.matches('.xxx')) {
    // выполнить обработку события клика на элементе с классом xxx
  }
});

// или, если классы могут добавляться динамически, то:

function handleXxxClick(e) {
  if (e.target.classList.contains('xxx')) {
    // выполнить обработку события клика на элементе с классом xxx
  }
}

body.addEventListener('click', handleXxxClick);
document.addEventListener('click', handleXxxClick, true); // для событий на управляемых элементах (какому классу относится body - см. Документацию)

// В случае динамически добавленных элементов с классом "xxx", добавьте следующий метод:

function addEventListenersToNewElements() {
  const newXxxElements = document.querySelectorAll('.xxx:not(:scope :global *)'); // исключить управляемые элементы (например, iframe), чтобы избежать дублирования обработчиков
  newXxxElements.forEach(element => {
    element.addEventListener('click', handleXxxClick);
  });
}

// Вызовите метод addEventListenersToNewElements() на каждом событии добавления элементов с классом "xxx", например:

document.addEventListener('DOMNodeInserted', (e) => {
  addEventListenersToNewElements(e.target);
});
```

Считанные отличия в сравнении с jQuery:

1. Вместо `$("body")` ищем элемент.body с помощью `document.body`.
2. Записываем все элементы с классом `xxx` в массив или NodeList для избежания поиска элементов на каждом событии, и располагаем их в слушателе события для тега body.
3. Проверяем условие на целевой элемент с помощью `matches()` или `classList.contains()`.
