    \begin{align}
      H(s) &= \frac{K}{s^2 + \left(\omega_c/q\right) s + \omega_c^2 } \\
      q &= \frac{1}{2}\left(\frac{\omega_C}{\omega_H} + \frac{\omega_L}{\omega_C} \right) \\
      \zeta &= \frac{1}{2}\left(\frac{\omega_C}{\omega_H} - \frac{\omega_L}{\omega_C} \right)
    \end{align}

    \item \textbf{Расчёт коэффициентов полюсов и нулей Лапласа}: Коэффициенты полюсов и нулей Лапласа имеют важное значение в анализе линейных систем в области временных задержек. Я разработал быстрый и точный алгоритм для вычисления этих коэффициентов для любых рациональных функций Лапласа с полиномиальными знаменателями и наивысшей степенью не более пяти.

    \begin{align}
      \text{Уравнение Лапласа: } H(s) &= \frac{N(s)}{D(s)} \\
      N(s) &= a_0 + a_1s + \cdots + a_ms^m \\
      D(s) &= b_0 + b_1s + \cdots + b_ns^n \\
      \text{Коэффициенты полюсов: } s_i &= -\frac{b_i}{a_i}, i=1,2,\ldots,m \\
      \text{Коэффициенты нулей: } s_j &= \frac{a_j}{b_j}, j=m+1,\ldots,m+n
    \end{align}

    \item \textbf{Распределение скоростей тока}: Распределение скоростей тока (ТДС) – это техника, которая измеряет скорость течения электрического тока в проводящей среде. Я разработал новую модель ТДС, которая используется для измерений в среде с разноориентированными проводящими частицами. Модель была опубликована в журнале IEEE Sensors Journal.

    \begin{align}
      V_p &= \frac{r_c}{\mu_0}\left(\ln{\left(\frac{2d}{r_c}\right)} - \frac{3}{4}\right)I \\
      V_z &= \frac{r_c}{\mu_0}\left(\ln{\left(\frac{2d}{r_c}\right)} + \frac{1}{2}\right)I \\
      \text{Скорость тока: } v_T &= \frac{V_p - V_z}{l} = \frac{r_c}{\mu_0 l}\left(\ln{\left(\frac{2d}{r_c}\right)} - \frac{1}{4}\right)I
    \end{align}

    где \(r_c\) - радиус проводящей частицы, \(d\) - средняя интерполяционная дистанция между проводящими частицами, \(\mu_0\) - магнитная проницаемость, \(l\) - длина исследуемого участка, \(I\) - ток.

