         ],
       ],
     },
   };
   ```

   A regra `vue/update-life-cycle-methods` cria um aviso se um dos métodos especificados em `methods` (hook de ciclo de vida):

   1. Altera diretamente uma propriedade interna do componente:

      ```javascript
      export default {
        data() {
          return { count: 0 };
        },
        methods: {
          increment() {
