      ```

   2. Chamada a um método que altera o estado interno do componente:

      ```javascript
      export default {
        data() {
          return { count: 0 };
        },
        methods: {
          increment() {
            // 💣 Erro: método altera o estado interno do componente
            this.changeCount(); // eslint-rule vulnerabilities/vue/no-mutating-external-state
